INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Cuando rompa a hervir añade el arroz y remueve bien. Luego baja el fuego hasta que todo quede burbujeando, pero muy suavemente.' FROM recipes WHERE name = 'Arroz con leche vegano' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
