INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'el grano debe estar blando pero firme en el centro. Continúa removiendo unos minutos hasta que espese un poco más, pero siga ligeramente líquido y cremoso.' FROM recipes WHERE name = 'Arroz con leche vegano' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
