INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Cuando esté caliente añade el ajo y deja que se cocine removiendo durante unos segundos para evitar que se dore.' FROM recipes WHERE name = 'Arroz pilaf con pasas y almendras' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
