INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta la parte verde y la base de la raíz del puerro y retira la hoja exterior de cada uno.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Corta la parte blanca en cilindros de 4-6 cm aproximadamente.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Empuja o saca con cuidado las capas internas de cada cilindro de puerro hasta dejar solo 2 o 3 capas exteriores.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Estas quedarán en forma de tubos o canelones. Trata de sacar al menos 12-16 tubos.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Corta finamente las capas internas que retiraste y resérvalas para el relleno.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Elimina el exceso de humedad del salmón con papel absorbente y salpimiéntalos.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Pon una sartén con AOVE a calentar a fuego medio.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Cocina los lomos de salmón por ambos lados, sin freír, hasta que la carne se deshaga fácilmente con una espátula.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Aparta el salmón a un lado en la misma sartén y añade los puerros cortados y el eneldo, cocina 2 minutos removiendo de vez en cuando y luego mezcla con el salmón.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Cocina hasta que el puerro esté suave y añade las espinacas crudas en tandas para integrarlas.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Pasa la mezcla de salmón, puerro y espinacas a un bol.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Agrega el requesón, una pizca de sal y pimienta al gusto, mezcla bien hasta tener una especie de pasta.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Engrasa un molde alto apto para horno con un poco de AOVE o de mantequilla.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Rellena cada canelón con la pasta anterior y colócalos ordenados en la bandeja. Reserva mientras preparas la salsa bechamel.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Pon la leche a calentar a fuego medio con un poco de sal.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'Añade la mantequilla y la nuez moscada rallada.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 16, 'Disuelve el kuzu en 15 ml de agua fría hasta que no queden grumos.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 17, 'Cuando la leche esté caliente y la mantequilla derretida, incorpora poco a poco el kuzu removiendo continuamente con una varilla para evitar que se formen grumos.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 18, 'Deja que se cocine sin dejar de remover hasta que la leche esté a punto de hervir y adquiera consistencia de crema.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 19, 'Retira del fuego.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
