INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 21, 'Precalienta el horno a 200 °C. Hornea los canelones 20 minutos o hasta que el queso se dore.' FROM recipes WHERE name = 'Canelones de puerro de salmón y requesón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
