INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Agrega los dientes de ajo machacados y deja que se cocine durante 1 minuto más sin dejar de remover.' FROM recipes WHERE name = 'Caponata siciliana clásica' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
