INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Cuando entre en ebullición, agrega la yuca y deja que se cocine en agua hirviendo hasta que esté blanda pero firme (que al pincharla tenga algo de resistencia).' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
