INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Corta los cilindros de yuca por la mitad y retira la vena gruesa del centro.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'En un bol, ralla la yuca por el lado grueso del rallador.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Luego añade el ajo, la cebolla y la sal, y remueve muy bien.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Engrásate un poco las manos y, con la yuca rallada, haz bolitas de 2 a 3 cm de diámetro.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Luego presiónalas entre las palmas hasta que tengan forma de tortita y ve colocándolas con cuidado en un plato.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Pon una sartén grande a fuego medio alto y añade el AOVE.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Cuando esté bien caliente añade los hash browns y deja que se cocinen durante 4 minutos por cada lado, hasta que estén dorados y tostaditos.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Si quieres que queden aún más crujientes, puedes tostarlos en el horno durante 10 minutos más.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Sirve los hash browns calientes con queso rallado, kétchup saludable o mermelada de tomates y pimientos.' FROM recipes WHERE name = 'Hash browns de yuca' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
