INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Pela las patatas y córtalas en cubos pequeños. Corta finamente la cebolla y el pimiento.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Corta también las tiras de beicon ahumado en trozos pequeños.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Pon al fuego una olla con suficiente agua y una pizca de sal, echa las patatas y cocínalas durante 5-7 minutos.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Escúrrelas y reserva.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Mientras se cocinan las patatas pon una sartén a fuego medio alto con la mitad del AOVE.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Añade los trocitos de beicon y deja que se cocine hasta que comiencen a dorarse.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Luego agrega la cebolla y el pimiento, y saltea durante un minuto.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Incorpora las patatas a la sartén con una pizca de sal y las hojuelas de pimentón.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Cocina removiendo constantemente hasta que las patatas se doren. Añade el perejil, remueve de nuevo y pásalas al plato de servir.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'En la misma sartén a fuego medio alto agrega el resto del AOVE.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Casca los huevos en un bol y, con cuidado de que la yema no se rompa, échalos a la sartén.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Cocina hasta que la clara esté cocida por completo, pero la yema todavía siga algo líquida o cruda (según el gusto).' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Sirve colocando los huevos estrellados sobre el hash de patatas. Esparce algo más de sal, pimienta y hojuelas de pimentón.' FROM recipes WHERE name = 'Huevos estrellados con hash de patatas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
