INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta la cebolla finamente. Desmenuza el queso feta con un tenedor y reserva.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Pon una sartén mediana a fuego medio alto y agrega el AOVE.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Cuando el aceite esté caliente, añade la cebolla y deja que se cocine hasta que esté blanda.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Agrega el eneldo, remueve y cocina durante 30 segundos.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Incorpora las espinacas y mézclalas con la cebolla hasta que las hojas se ablanden.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Si no caben de una vez en la sartén, añádelas por partes hasta que todas estén incorporadas.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Por último, agrega 3/4 del queso feta, una pizca de sal y pimienta al gusto (recuerda que el queso es salado).' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Cocina todo a fuego alto sin dejar de remover para que se evapore la mayor cantidad del líquido que desprenden las espinacas y el queso.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Retira del fuego y distribuye las espinacas en dos cuencos o platos hondos.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Para pochar los huevos, pon un cazo pequeño con al menos 5 cm de agua con vinagre a hervir y casca un huevo en un bol pequeño.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Cuando rompa a hervir baja el fuego. Remueve rápidamente el agua con una cuchara para hacer que gire y añade el huevo justo en el vórtice de agua que se forma (no introduzcas la cuchara de nuevo).' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Deja que se cocine allí sin tocarlo entre 1 y 2 minutos.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Luego saca el huevo con una espumadera (procurando que la yema no se rompa) para que escurra el agua.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Colócalo con cuidado sobre uno de los cuencos con la spanakopita. Repite el procedimiento con el otro huevo.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Añade a cada cuenco el queso feta restante por encima, las nueces partidas, un chorrito de nata y la pimienta recién molida.' FROM recipes WHERE name = 'Huevos pochados con spanakopita (empanada griega de espinacas)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
