INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta finamente la cebolla, el ajo y el pimiento verde.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Retira las semillas del pimiento verde picante y córtalo en rodajas muy finas. Corta las hojitas de cilantro y el aguacate en cubitos.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
