INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Pon la sartén a fuego medio y agrega el AOVE. Cuando esté caliente, añade todos los vegetales menos el tomate.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Cocínalos removiendo durante un minuto.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Pasa los tomates troceados por un colador y escurre el exceso de líquido de la conserva (guárdalo para una salsa).' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Luego añádelos a la sartén, salpimienta, y deja que se cocine todo un minuto más.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
