INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Luego, con la misma cuchara, abre pequeños espacios en la fuente donde colocarás los huevos, con cuidado de que las yemas no se rompan.' FROM recipes WHERE name = 'Huevos rancheros horneados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
