INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Prepara el hummus tradicional.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Enjuaga los garbanzos de bote y exprime el limón. Si quieres reducir el sabor fuerte del ajo crudo, introdúcelo 30 segundos con la piel en el microondas.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Pon los garbanzos en un procesador de alimentos. Añade el agua, el zumo de limón, el yogur griego, el ajo pelado, el comino, el AOVE, la sal y por último el tahini (o las semillas de sésamo).' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Procesa los ingredientes hasta tener una pasta cremosa y homogénea. Prueba el hummus y ajusta la cantidad de sal y limón.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Si te ha quedado muy espeso, añade una cucharadita de agua o de AOVE.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Pasa el hummus a un bol y divide en tres porciones.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Pon una porción en un bote de cristal, cúbrelo con un poco de AOVE y espolvorea con el pimentón. Reserva.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Devuelve otra porción al procesador. Seca muy bien con papel absorbente los espárragos de bote, córtalos y añádelos junto con el curri.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Procesa hasta que los espárragos se integren por completo y el hummus se coloree de amarillo intenso.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Pasa a un bote de cristal, cúbrelo con un poco de AOVE y añade unas hojitas de perejil al gusto. Reserva.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Enjuaga el procesador. Añade la porción de hummus restante y la remolacha en trozos.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Procesa todo de nuevo hasta que la remolacha esté integrada por completo y el hummus adquiera un color rosado intenso. Pasa a un bote de cristal, cubre con un poco de AOVE y esparce las almendras fileteadas tostadas y una pizca de sal.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Sirve los hummus de tres colores con rodajas de pan de trigo sarraceno tostadas, steaks de vegetales, spicy nuts o una ensalada verde.' FROM recipes WHERE name = 'Hummus tres colores, para compartir' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
