INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Seca un poco los filetes de hígado con papel absorbente y córtalo en trozos del tamaño de un bocado.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Corta la cebolla y el beicon en trozos pequeños y machaca el ajo.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Mezcla en un bol grande el AOVE, la mitad del ajo machacado, el orégano, el comino, el pimentón, la sal y la pimienta.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Luego añade el hígado y remueve bien.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Pon a calentar a fuego medio alto una sartén antiadherente y saltea el beicon unos minutos, hasta que suelte parte de la grasa.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Añade la cebolla y el resto del ajo, y deja que se cocine removiendo hasta que queden blandos.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Pasa el beicon y la cebolla a un bol dejando gran parte de la grasa en la sartén. Reserva.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Sube la temperatura de la sartén y, cuando esté bien caliente, añade el hígado.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Saltéalo removiendo durante 3 minutos, hasta que dore por todos los lados.' FROM recipes WHERE name = 'Hígado encebollado con beicon' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
