INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Con las manos haz bolitas con la masa (de 30-50 g cada una, para galletas de 5 cm de diámetro, más o menos).' FROM recipes WHERE name = 'Las mejores cookies de avena y chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
