INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Añade el fumet de pescado, el vinagre y la pasta de tomate, y remueve hasta que se integre todo.' FROM recipes WHERE name = 'Mejillones al vapor con tomate y ajo' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
