INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Pon a calentar a fuego medio una olla pequeña con el agua y diluye en ella el edulcorante.' FROM recipes WHERE name = 'Mermelada de tomates y pimientos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
