INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Remueve bien, baja la temperatura y tapa la olla. Cocina a fuego bajo durante 35-40 minutos removiendo de vez en cuando.' FROM recipes WHERE name = 'Mermelada de tomates y pimientos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'El pimiento debe estar muy blando y el tomate casi deshecho. Añade el pimentón molido si te gusta el picante.' FROM recipes WHERE name = 'Mermelada de tomates y pimientos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Si la mermelada está muy líquida y has usado miel como edulcorante, deja que se cocine un poco más hasta reducir el líquido y tener una textura tipo almíbar.' FROM recipes WHERE name = 'Mermelada de tomates y pimientos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Si empleaste otro edulcorante, disuelve el kuzu en 30 ml de agua fría y añádelo a la olla sin dejar de remover.' FROM recipes WHERE name = 'Mermelada de tomates y pimientos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
