INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta finamente el ajo y la cebolla. Quita el tallo grueso a las hojas de espinacas y córtalas en trozos grandes si están enteras.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Pon una olla grande a fuego medio y añade el AOVE.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Cuando se haya calentado un poco agrega la cebolla y el ajo, y deja que se cocinen removiendo sin parar durante 2 minutos.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Añade el caldo y el tomate envasado, y lleva a ebullición.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Cuando el líquido comience a hervir añade la menestra de verdura congelada y una pizca de sal.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Espera a que entre en ebullición de nuevo. Luego baja el fuego, tapa la olla y deja que se cocine 10 minutos más removiendo de vez en cuando.' FROM recipes WHERE name = 'Minestrone fácil de congelados' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
