INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Mientras, monta las cestitas de jamón: coloca una o dos lonchas de jamón cubriendo las paredes y el fondo de cada espacio del molde para magdalenas.' FROM recipes WHERE name = 'Minifrittatas de calabacín y jamón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Casca los huevos en un bol y añade la nata, el ajo y un poco de sal y pimienta al gusto.' FROM recipes WHERE name = 'Minifrittatas de calabacín y jamón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Bátelos con un tenedor hasta lograr una mezcla homogénea.' FROM recipes WHERE name = 'Minifrittatas de calabacín y jamón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
