INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Retira del fuego y espera a que los vegetales se enfríen un poco antes de mezclarlos con los huevos.' FROM recipes WHERE name = 'Minifrittatas de calabacín y jamón' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
