INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Cuando la masa haya fermentado esparce las semillas por toda la superficie del pan presionándolas ligeramente para adherirlas a la masa.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Precalienta el horno a 180 °C con ventilador, introduce el molde y hornea durante 40 minutos, controlando de vez en cuando para que no se quemen la superficie ni las semillas.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Al acabar el tiempo verifica la cocción introduciendo un palito largo de madera en el centro del pan.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Si sale con restos de masa, hornea 5-10 minutos más; si sale limpio, estará listo.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Saca el pan del horno y deja que se enfríe en el molde unos minutos.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'Luego retira el molde y colócalo en una rejilla para que se enfríe por completo.' FROM recipes WHERE name = 'Pan fácil de trigo sarraceno' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
