INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Limpia bien las patatas con agua y un cepillo pequeño.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
