INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Pon las patatas en una olla o sartén grande y añade agua hasta cubrirlas a un poco más de la mitad.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Echa suficiente sal, tapa la sartén y deja que se cocinen a fuego medio alto hasta que estén blandas pero firmes (más o menos 20 minutos).' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Retíralas del agua y espera a que se enfríen un poco.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Deja una patata en la tabla de cortar y, usando otra tabla o el fondo de una sartén, aplástala presionando con cuidado para que se mantenga entera.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Con una espátula, despega la patata de la tabla y ponla sobre un plato. Repite este procedimiento con todas las patatas.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Calienta una sartén antiadherente a fuego medio con 15 ml de AOVE.' FROM recipes WHERE name = 'Patatas doradas con beicon y chalotas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
