INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Pela y corta 3 dientes de ajo en láminas gruesas. Haz pequeños ramitos de romero.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'En un mortero añade los dos dientes de ajo restantes, las anchoas con un poco de su aceite, 30 ml de AOVE y unas hojitas de romero.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Machaca y mezcla muy bien hasta obtener una especie de pasta.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
