INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Con la punta de un cuchillo haz pequeñas incisiones alrededor de la pierna e introduce en cada incisión 1 lámina de ajo y una ramita de romero empujándolas hacia el interior con el dedo.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
