INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Pon la pierna en una bandeja de horno con el lado del muslo mirando hacia abajo.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Con una brocha de cocina, unta con la mezcla de ajo, anchoas y romero.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Guarda lo que sobre para untarlo después de nuevo.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Precalienta el horno a 170 °C con calor arriba y abajo.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Añade el agua y el vinagre en el fondo de la bandeja, y mete el cordero en el horno durante 1 hora.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Puedes cocinarlo a una temperatura menor, 150 °C, durante 2 horas, pero ve añadiendo agua a medida que vaya secándose.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'El cordero estará listo cuando alcance una temperatura interna de entre 55 y 60 °C.' FROM recipes WHERE name = 'Pierna de cordero asada a fuego lento' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
