INSERT INTO recipe_ingredients (recipe_id, position, food, quantity, unit) SELECT id, 3, 'Orégano seco', 1, 'gr' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_ingredients (recipe_id, position, food, quantity, unit) SELECT id, 4, 'Pimienta', NULL, NULL FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_ingredients (recipe_id, position, food, quantity, unit) SELECT id, 5, 'Aceite de oliva virgen extra (AOVE)', 15, 'gr' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Limpia el pollo de cualquier resto de plumas en la piel o de órganos internos (en caso de que los tenga, guarda el hígado y el corazón para hacer un caldo).' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Para hacer el corte parrillero o mariposa, coloca el pollo con la pechuga hacia la tabla de cortar.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Sostenlo con firmeza con una mano mientras comienzas a desprender la columna vertebral del pollo con una tijera de cocina, comenzando el corte donde se une el final del muslo con la rabadilla (cola).' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Sigue cortando lo más cerca posible del hueso de la columna (no sobre esta).' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Si el corte está muy separado de los huesos de la columna, tropezarás con el del muslo, que será muy difícil de cortar.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Si te ocurre esto, mueve la tijera hacia dentro y corta alrededor del hueso del muslo.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Luego corta las costillas hasta el cuello para separar por completo un lado de la columna del pollo.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Repite este mismo procedimiento por el otro lado, hasta tener el pollo completamente abierto por la espalda.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Puedes guardar los huesos de la columna para hacer un caldo de huesos.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Dale la vuelta al pollo y mete las puntas de las alas debajo de los lados de la pechuga.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Luego, con la palma de la mano, presiona la pechuga contra la tabla hasta que quede plana por completo (es probable que oigas que los huesos se fracturan).' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Para la marinada, pela y machaca los dientes de ajo.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Añádelos a un bol junto con la mostaza, las hierbas aromáticas, el zumo, la piel del limón y el AOVE.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Pela y corta por la mitad a lo largo las chalotas (si las usas).' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Seca bien la piel del pollo con papel absorbente.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'Con los dedos, separa con cuidado la piel de las pechugas y de los traseros. Distribuye el aderezo y frota todo el pollo con él de manera uniforme (incluye la parte inferior) y en especial bajo la piel que has levantado.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 16, 'Cuando el pollo esté embadurnado por completo, sazónalo bien por todos lados con suficiente sal.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 17, 'Deja que se marine al menos durante 15 minutos a temperatura ambiente mientras el horno se precalienta a 180 °C con ventilador.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 18, 'Dispón el pollo en la bandeja de horno con la pechuga y los muslos hacia arriba, y mete debajo las chalotas y las ramitas de hierbas aromáticas.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 19, 'Introduce la bandeja en el horno y deja que se cocine destapado entre 40 y 50 minutos.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 20, 'El pollo estará listo cuando la parte más gruesa de la pechuga registre al menos 68 °C de temperatura.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 21, 'Después de los primeros 25 minutos de cocción mide la temperatura y rocíalo con sus propios jugos.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 22, 'Puedes repetir este procedimiento antes de terminar el tiempo de cocción.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 23, 'Saca el pollo del horno y deja que repose unos minutos descubierto para que la piel no pierda la textura del tostado.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 24, 'Luego corta al gusto.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 25, 'Pasa las chalotas y los jugos de la bandeja a través de un colador de malla fina.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 26, 'Apriétalos contra la malla para extraer el sabor y lograr una salsa rápida. Puedes añadirla al pollo justo antes de servir.' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_materials (recipe_id, name) SELECT id, 'Tabla de cortar' FROM recipes WHERE name = 'Pollo asado (estilo mariposa o listo para la parrilla)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
