INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Limpia la carne de cualquier exceso de grasa.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Corta la cebolla blanca y el pimentón rojo en trozos grandes.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Ponlos en un procesador de alimentos junto con el ajo, 25 ml de AOVE, la salsa de soja, el orégano, la sal y la pimienta.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Procesa todo mediante pulsaciones hasta que los vegetales estén finamente cortados, pero no triturados.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Mete la carne en un envase de vidrio (o en una bolsa grande con cierre de zip).' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Añade los vegetales triturados junto con el vino tinto y el tomate triturado.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Tapa el recipiente y mueve para que la carne se impregne con la marinada.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Deja marinando en la nevera entre 8 y 24 horas y dale la vuelta de vez en cuando.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Saca la carne de la marinada al menos una hora antes de prepararla, para que esté a temperatura ambiente (o métela en el microondas a potencia mínima durante 2 minutos).' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Guarda la marinada de nuevo en la nevera.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Ralla o corta la panela en trocitos (si no es granulada) y reserva.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Pon una sartén a fuego fuerte y añade 25 ml de AOVE.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Cuando esté bien caliente, echa la carne en la sartén y dora de manera uniforme (15 minutos).' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Pasa la carne a la Instapot (o a la olla de presión), añade la marinada, el agua, la panela y la hojita de laurel.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Cocina durante 50 minutos (en presión alta en la Instapot) y deja que la presión se libere lentamente;' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'al pinchar la carne esta debe estar blanda pero firme.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 16, 'Saca la carne a una tabla de cortar y desecha la hoja de laurel.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 17, 'Corta el redondo en rodajas de 1 cm más o menos con un cuchillo bien afilado para no romper los bordes.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 18, 'Reserva.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 19, 'Desgrasa la salsa que ha quedado en la olla si es necesario.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 20, 'Cuando se enfríe un poco, mete la batidora de brazo en la olla y tritura para espesarla.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 21, 'Si todavía está muy líquida, hiérvela con suavidad hasta que se reduzca un poco más y alcance la consistencia deseada.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 22, 'Dispón la carne en una fuente para servir y báñala con la salsa caliente. Acompaña con arroz basmati o patatas cocidas.' FROM recipes WHERE name = 'Redondo de añojo asado' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
