INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta las setas en láminas o trozos pequeños. Corta la cebolleta a lo largo y luego en láminas (guarda la parte verde de la cebolleta para servir).' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
