INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Quita la piel al chorizo y desmenuza la carne.' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Precalienta la sartén a fuego medio bajo. Echa el AOVE, distribúyelo y espera a que se caliente.' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Añade el chorizo y sofríe durante un minuto. Luego, agrega la cebolleta y el ajo, y deja que se cocine hasta que empiecen a ablandarse.' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
