INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Casca los huevos en un bol, sazónalos y bátelos con un tenedor.' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
