INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Sirve el revuelto esparciendo por encima la parte verde de la cebolleta y la pimienta recién molida, a tu gusto.' FROM recipes WHERE name = 'Revuelto de setas (con o sin chorizo)' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
