INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Pon el arroz en un colador y lávalo bajo agua corriente hasta que el agua salga transparente.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Deja que escurra un poco.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Corta la base dura de los espárragos.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Extiéndelos en un plato apto para microondas y cúbrelos con papel absorbente un poco húmedo.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Cocina 3 minutos en el microondas a máxima potencia. Retira las servilletas y espera a que se enfríen (también puedes blanquearlos como en la ensalada de primavera, ver receta).' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Corta los espárragos en rodajas pequeñas (1 cm), pero deja las puntas largas para servir.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Corta finamente la cebolla, el ajo y el perejil.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Echa el caldo de pollo y el agua en una olla pequeña, y lleva a ebullición;' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'luego baja la temperatura y mantenlo caliente.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Pon una olla mediana a fuego medio y derrite 15 g de mantequilla, añade la cebolla y sofríela hasta que se ablande, luego agrega el ajo y deja que se cocine 30 segundos más.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Pon el arroz en la olla y remueve hasta cubrir todos los granos con mantequilla (2 minutos).' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Luego añade el vino blanco y una pizca de sal y pimienta, y, sin dejar de remover, espera a que hierva para que se evapore el alcohol y el arroz absorba parte del líquido.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Agrega casi todo el caldo caliente, deja cerca de 100 ml para el final, remueve y lleva a ebullición.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Luego baja la temperatura hasta que quede burbujeando, pero muy suavemente. Tapa la olla y deja que se cocine durante 20 minutos removiéndolo al menos dos veces durante este tiempo.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Destapa y prueba el arroz, el grano debería estar todavía un poco duro.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'Añade el resto del caldo caliente, los espárragos cortados (menos las puntas), 15 g de mantequilla y el queso parmesano, y, removiendo muy lentamente, deja que se cocine 5 minutos más hasta que el risotto termine la cocción y esté cremoso.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 16, 'Retira del fuego, tapa y deja que repose al menos durante 5 minutos.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 17, 'Si te ha quedado muy espeso, agrega un poco más de caldo o agua.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 18, 'Coloca encima las puntas de los espárragos, el perejil y un poco más de pimienta u hojuelas de pimentón picante y sirve de inmediato.' FROM recipes WHERE name = 'Risotto fácil de espárragos' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
