INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Rehidrata la pasta de arroz: Remoja los fideos en agua hirviendo durante 3 o 4 minutos, luego pásalos a un colador y enfríalos un poco con agua corriente.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Deja que escurran hasta que vayas a montar los rollos.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Seca las gambas con papel absorbente y córtalas por la mitad a lo largo (lomo).' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Corta las zanahorias y el pimiento rojo en tiras o bastones muy finos.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Lava las hojas de lechuga, córtalas por la mitad larga y quítales las partes duras del tallo.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 5, 'Corta el cebollino en dos y separa las hojitas de hierbabuena y de cilantro del tallo.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Acomoda todos estos ingredientes en una bandeja para que sea más fácil rellenar los rollitos.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 7, 'Usa entre 1/4 y 1/2 de cada ingrediente para llenar cada rollito.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Echa de 1 a 2 cm de agua tibia en un plato hondo o recipiente donde quepa cómodamente el papel de arroz.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Sumerge el papel y espera a que comience a ablandarse.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Sácalo del agua con cuidado, deja que escurra un poco y pásalo rápidamente a una superficie lisa y seca, como una tabla de cortar.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 11, 'Dispón en el centro del papel de arroz un trozo de lechuga y, encima, una porción de la pasta de arroz.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 12, 'Luego coloca algunos bastones de zanahoria y de pimiento, y un trozo de aguacate.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 13, 'Por último, agrega las hojas de cebollino, de cilantro y de hierbabuena.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 14, 'Dobla la parte inferior del papel de arroz sobre el relleno y luego dobla los lados izquierdo y derecho asegurándote de que el relleno quede envuelto.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 15, 'En la parte superior que falta por doblar coloca las 4 mitades de gambas horizontalmente con el lado naranja hacia abajo.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 16, 'Coge el rollo por el relleno y sigue enrollándolo sobre las gambas hasta cerrarlo.' FROM recipes WHERE name = 'Rollos vietnamitas de gambas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
