INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Luego salpimienta y deja que repose unos minutos.' FROM recipes WHERE name = 'Solomillo de cerdo balsámico con cebollas caramelizadas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
