INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Selecciona en la Instapot la opción de saltear, «sauté», a fuego medio.' FROM recipes WHERE name = 'Tacos de carne mechada con tortillas de legumbres' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
