INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Tapa la Instapot y selecciona la función de cocción a alta presión.' FROM recipes WHERE name = 'Tacos de carne mechada con tortillas de legumbres' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
