INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Cúbrela con agua suficiente, lleva a ebullición y deja que se cocine durante una hora.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 2, 'Saca la naranja del agua y cuando esté tibia córtala por la mitad y retira las semillas.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Introduce la naranja cocida con piel en un procesador de alimentos y procesa hasta obtener un puré.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Precalienta el horno a 170 °C. Cubre el molde con papel de hornear o engrásalo si es antiadherente o de silicona.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
