INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 6, 'Añade el puré de naranja, las almendras molidas y el polvo de hornear, y mezcla con una espátula hasta que todo esté integrado.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
