INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Añade poco a poco la crema de yemas con naranja a las claras montadas, mezclando de forma envolvente hasta integrarla por completo.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 9, 'Añade las chispas de chocolate negro y sigue mezclando de forma envolvente.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 10, 'Vierte en el molde y da unos golpecitos contra la superficie de trabajo para que la mezcla se distribuya de manera uniforme.' FROM recipes WHERE name = 'Tarta de naranja, almendras y chispas de chocolate' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
