INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 1, 'Mete en el microondas y deja que se cocine a potencia media durante 30 segundos.' FROM recipes WHERE name = 'Trucha con jamón y picada' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
