INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Procesa mediante pulsaciones hasta que quede todo cortado pero no triturado.' FROM recipes WHERE name = 'Trucha con jamón y picada' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 4, 'Limpia y seca bien las truchas con papel absorbente.' FROM recipes WHERE name = 'Trucha con jamón y picada' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
