INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 8, 'Añade parte de la picada por encima y reserva un poco para servir.' FROM recipes WHERE name = 'Trucha con jamón y picada' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
