INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 0, 'Corta en láminas gruesas las setas grandes y deja enteras las más pequeñas.' FROM recipes WHERE name = 'Wok de setas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
