INSERT INTO recipe_steps (recipe_id, position, text) SELECT id, 3, 'Mezcla en un bol la salsa de soja y el agua, y disuelve allí el almidón de maíz (si lo usas).' FROM recipes WHERE name = 'Wok de setas' AND name NOT IN (SELECT name FROM _nutrirutina_skip);
